merged_chunks = [
    {"id": "c1", "text": "Refunds are processed within five business days."},
    {"id": "c2", "text": "Refunds are processed within five business days."},
    {"id": "c3", "text": "Refund processing typically takes about five business days."},
    {"id": "c4", "text": "Shipping usually takes one to two weeks."},
]

def remove_exact_duplicates(chunks):
    # removes exact string matches
    seen_texts = set()
    result = []
    for c in chunks:
        if c["text"] not in seen_texts:
            seen_texts.add(c["text"])
            result.append(c)
    return result

def word_overlap_ratio(a, b):
    words_a, words_b = set(a.lower().split()), set(b.lower().split())
    return len(words_a & words_b) / len(words_a | words_b)

def remove_near_duplicates(chunks, threshold=0.6):
    # removes paraphrased near duplicates using word overlap
    result = []
    for c in chunks:
        if not any(word_overlap_ratio(c["text"], kept["text"]) > threshold for kept in result):
            result.append(c)
    return result

after_exact = remove_exact_duplicates(merged_chunks)
print(f"After removing exact duplicates: {len(after_exact)} chunks")

after_near = remove_near_duplicates(after_exact)
print(f"After removing near duplicates: {len(after_near)} chunks")
for c in after_near:
    print(f"  {c}")
